import React, { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import CreateCoinflipModal from '../components/CreateCoinflipModal';
import LeaderboardModal from '../components/LeaderboardModal';
import AnimatedPopup from '../components/AnimatedPopup';
import './CoinflipPage.css';

const CoinflipPage = ({ socket, setBalance }) => {
  const { user } = useAuth();
  const [coinflips, setCoinflips] = useState([]);
  const [activeCount, setActiveCount] = useState(0);
  const [totalInGames, setTotalInGames] = useState(0);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showLeaderboard, setShowLeaderboard] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [sortBy, setSortBy] = useState('newest');
  const [loading, setLoading] = useState(true);
  const [userInventory, setUserInventory] = useState([]);

  // Join modal state
  const [showJoinModal, setShowJoinModal] = useState(false);
  const [selectedBet, setSelectedBet] = useState(null);
  const [joinSelectedItems, setJoinSelectedItems] = useState([]);
  const [joining, setJoining] = useState(false);

  // Coin flip result animation state
  const [activeFlipResult, setActiveFlipResult] = useState(null);
  const [isFlipping, setIsFlipping] = useState(false);

  // Popup state
  const [showPopup, setShowPopup] = useState(false);
  const [popupMessage, setPopupMessage] = useState('');
  const [popupType, setPopupType] = useState('info');

  const showCustomPopup = (message, type = 'info') => {
    setPopupMessage(message);
    setPopupType(type);
    setShowPopup(true);
    setTimeout(() => {
      setShowPopup(false);
    }, 3000);
  };

  const closePopup = () => {
    setShowPopup(false);
  };

  // Fetch coinflips
  const fetchCoinflips = useCallback(async () => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/coinflip?sort=${sortBy}`);
      if (response.ok) {
        const data = await response.json();
        setCoinflips(data.coinflips || []);
        setActiveCount(data.activeCount || 0);
        setTotalInGames(data.totalInGames || 0);
      } else if (response.status === 429) {
        showCustomPopup('Server is rate-limiting requests — wait a few seconds and refresh.', 'error');
      }
    } catch (error) {
      console.error('Error fetching coinflips:', error);
    } finally {
      setLoading(false);
    }
  }, [sortBy]);

  // Fetch user inventory
  const fetchInventory = useCallback(async () => {
    if (!user) return;
    try {
      const identifier = user.id || user.robloxUsername;
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/users/inventory/${identifier}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });
      if (response.ok) {
        const data = await response.json();
        setUserInventory(data.items || []);
      }
    } catch (error) {
      console.error('Error fetching inventory:', error);
    }
  }, [user]);

  // Initial load and socket listeners
  useEffect(() => {
    fetchCoinflips();
    fetchInventory();

    if (socket) {
      socket.on('newCoinflip', (data) => {
        setCoinflips(prev => [data, ...prev.filter(cf => cf.id !== data.id)]);
        setActiveCount(prev => prev + 1);
        setTotalInGames(prev => prev + (data.totalValue || 0));
      });

      socket.on('coinflipJoined', (data) => {
        setCoinflips(prev => prev.map(cf => cf.id === data.id ? data : cf));
      });

      socket.on('coinflipResult', (data) => {
        // If current user is either creator or opponent, trigger the flip modal
        if (data && user && (data.creatorId === user.id || data.opponentId === user.id)) {
          triggerCoinflipAnimation(data);
          fetchInventory();
        }
        setCoinflips(prev => prev.map(cf => cf.id === data.id ? data : cf));
      });
    }

    return () => {
      if (socket) {
        socket.off('newCoinflip');
        socket.off('coinflipJoined');
        socket.off('coinflipResult');
      }
    };
  }, [socket, user, fetchCoinflips, fetchInventory]);

  const triggerCoinflipAnimation = (gameData) => {
    setActiveFlipResult(gameData);
    setIsFlipping(true);

    // Stop spin animation after 3.2 seconds
    setTimeout(() => {
      setIsFlipping(false);
    }, 3200);
  };

  const handleCreateBet = () => {
    if (!userInventory || userInventory.length === 0) {
      showCustomPopup('You currently have no items in your inventory to bet.', 'warning');
      return;
    }
    setShowCreateModal(true);
  };

  // Called by the create modal on success: post the new bet into the
  // current list immediately, then refetch to reconcile with the server.
  const handleBetCreated = (newBet) => {
    if (newBet && newBet.id) {
      setCoinflips((prev) => [newBet, ...prev.filter((cf) => cf.id !== newBet.id)]);
      setActiveCount((prev) => prev + 1);
      setTotalInGames((prev) => prev + (newBet.totalValue || 0));
      showCustomPopup('Coinflip created — your bet is live!', 'success');
    }
    fetchCoinflips();
    fetchInventory();
  };

  const handleOpenJoinModal = (bet) => {
    if (!userInventory || userInventory.length === 0) {
      showCustomPopup('You currently have no items in your inventory to bet with.', 'warning');
      return;
    }
    setSelectedBet(bet);
    setJoinSelectedItems([]);
    setShowJoinModal(true);
  };

  const toggleJoinItemSelection = (item) => {
    const targetId = item.itemId || item.id;
    setJoinSelectedItems(prev => {
      const exists = prev.some(i => (i.itemId || i.id) === targetId);
      if (exists) {
        return prev.filter(i => (i.itemId || i.id) !== targetId);
      } else {
        return [...prev, item];
      }
    });
  };

  const getJoinTotalValue = () => {
    return joinSelectedItems.reduce((sum, item) => sum + (item.value || item.details?.value || 0), 0);
  };

  const handleConfirmJoinBet = async () => {
    if (!selectedBet || joinSelectedItems.length === 0) {
      showCustomPopup('Please select at least one item to match the bet.', 'warning');
      return;
    }

    setJoining(true);
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/coinflip/${selectedBet.id}/join`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          selectedItems: joinSelectedItems.map(item => ({
            itemId: item.itemId || item.id,
            name: item.details?.name || item.name,
            quantity: 1,
            value: item.value || item.details?.value || 0
          }))
        })
      });

      const data = await response.json();

      if (response.ok) {
        setShowJoinModal(false);
        triggerCoinflipAnimation(data);

        if (socket) {
          socket.emit('coinflipJoined', data);
          socket.emit('coinflipResult', data);
        }

        fetchInventory();
        fetchCoinflips();
      } else {
        showCustomPopup(data.message || 'Failed to join coinflip', 'error');
      }
    } catch (err) {
      console.error('Error joining coinflip:', err);
      showCustomPopup('Failed to join coinflip due to server error', 'error');
    } finally {
      setJoining(false);
    }
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading coinflips...</p>
      </div>
    );
  }

  return (
    <div className="coinflip-page">
      <div className="page-header">
        <h1>Coinflip</h1>
        <div className="page-stats">
          <span>{activeCount} Active Games</span>
          <span>{totalInGames.toLocaleString()} AMP in Games</span>
        </div>
        <div className="page-actions">
          <select 
            value={sortBy} 
            onChange={(e) => setSortBy(e.target.value)}
            className="sort-select"
          >
            <option value="newest">Newest</option>
            <option value="oldest">Oldest</option>
            <option value="value_high">Value High to Low</option>
            <option value="value_low">Value Low to High</option>
          </select>
          <button 
            className="btn btn-primary bet-items-btn" 
            onClick={handleCreateBet}
          >
            + BET ITEMS
          </button>
          <button 
            className="btn btn-secondary"
            onClick={() => setShowLeaderboard(true)}
          >
            LEADERBOARD
          </button>
          <button 
            className="btn btn-secondary"
            onClick={() => setShowHistory(true)}
          >
            HISTORY
          </button>
        </div>
      </div>

      {/* Current bets section */}
      <div className="current-bets-section card">
        <h3>Current Active Games</h3>
        {coinflips.filter(cf => cf.status === 'waiting' || cf.status === 'active').length === 0 ? (
          <div className="no-bets-placeholder">
            <p>No current active bets</p>
            <p>Click "BET ITEMS" above to create your game!</p>
          </div>
        ) : (
          <div className="coinflip-list">
            {coinflips.filter(cf => cf.status === 'waiting' || cf.status === 'active').map(coinflip => {
              const creatorName = coinflip.creator?.displayName || coinflip.creatorUsername || 'Unknown';
              const creatorAvatar = coinflip.creator?.avatar || coinflip.creatorAvatar || '/default-avatar.png';
              const creatorSide = coinflip.sideChosen || coinflip.creatorSide || 'heads';
              const isUserCreator = user && (coinflip.creatorId === user.id);

              return (
                <div key={coinflip.id} className="coinflip-bet-summary">
                  <div className="bet-info">
                    <div className="bet-creator">
                      <img 
                        src={creatorAvatar} 
                        alt={`${creatorName}'s avatar`}
                        className="bet-creator-avatar"
                        onError={(e) => { e.target.src = '/default-avatar.png'; }}
                      />
                      <div className="bet-details">
                        <div className="creator-name">
                          {creatorName} {isUserCreator && <span className="own-badge">YOU</span>}
                        </div>
                        <div className="bet-value">{(coinflip.totalValue || 0).toLocaleString()} AMP</div>
                      </div>
                    </div>

                    <div className="bet-side">
                      <span className={`side-indicator ${creatorSide}`}>
                        Side: {creatorSide.toUpperCase()}
                      </span>
                    </div>

                    <div className="bet-range-info">
                      <span className="range-label">Accepts</span>
                      <span className="range-value">Any value</span>
                    </div>

                    <div className="bet-actions">
                      {!isUserCreator ? (
                        <button 
                          className="btn btn-primary"
                          onClick={() => handleOpenJoinModal(coinflip)}
                        >
                          Join Bet
                        </button>
                      ) : (
                        <span className="waiting-pill">Waiting for opponent...</span>
                      )}
                    </div>
                  </div>

                  {/* Show creator items */}
                  {coinflip.creatorItems && coinflip.creatorItems.length > 0 && (
                    <div className="bet-items-row">
                      {coinflip.creatorItems.map((item, idx) => (
                        <div key={idx} className="bet-item-chip" title={`${item.name || item.itemName} (${item.value} AMP)`}>
                          <img 
                            src={item.image || item.imageUrl || '/default-item.png'} 
                            alt={item.name} 
                            className="chip-img"
                            onError={(e) => { e.target.src = '/default-item.png'; }}
                          />
                          <span className="chip-name">{item.name || item.itemName}</span>
                          <span className="chip-val">{(item.value || 0).toLocaleString()} AMP</span>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Coin Flip Result Animation Modal */}
      {activeFlipResult && (
        <div className="modal-overlay" onClick={() => !isFlipping && setActiveFlipResult(null)}>
          <div className="flip-result-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Coinflip Battle</h2>
              {!isFlipping && (
                <button className="close-modal" onClick={() => setActiveFlipResult(null)}>×</button>
              )}
            </div>

            <div className="flip-modal-body">
              <div className="battle-vs-header">
                <div className="battle-player">
                  <span className="player-title">Creator ({activeFlipResult.creatorSide?.toUpperCase()})</span>
                  <span className="player-display-name">{activeFlipResult.creatorUsername || activeFlipResult.creator?.displayName}</span>
                </div>
                <div className="battle-vs-badge">VS</div>
                <div className="battle-player">
                  <span className="player-title">Opponent ({activeFlipResult.opponentSide?.toUpperCase() || (activeFlipResult.creatorSide === 'heads' ? 'TAILS' : 'HEADS')})</span>
                  <span className="player-display-name">{activeFlipResult.opponentUsername || activeFlipResult.opponent?.displayName || 'Opponent'}</span>
                </div>
              </div>

              {/* 3D Animated Coin */}
              <div className="coin-animation-container">
                <div className={`coin-3d ${isFlipping ? `flipping-${activeFlipResult.result || 'heads'}` : `landed-${activeFlipResult.result || 'heads'}`}`}>
                  <div className="coin-face heads-face">H</div>
                  <div className="coin-face tails-face">T</div>
                </div>
                <div className="coin-shadow"></div>
              </div>

              {isFlipping ? (
                <div className="flipping-indicator">
                  <div className="flipping-pulse"></div>
                  <p>Flipping the coin...</p>
                </div>
              ) : (
                <div className="result-announcement">
                  <div className="outcome-banner">
                    The coin landed on <strong className={`outcome-word ${activeFlipResult.result}`}>{activeFlipResult.result?.toUpperCase()}</strong>!
                  </div>
                  <div className="winner-declaration">
                    🏆 <span>{activeFlipResult.winnerUsername}</span> Wins the Pot!
                  </div>
                  <div className="pot-won-banner">
                    Total Pot: <strong>{(activeFlipResult.totalValue || 0).toLocaleString()} AMP</strong>
                  </div>
                  <button 
                    className="btn btn-primary close-result-btn"
                    onClick={() => setActiveFlipResult(null)}
                  >
                    Collect & Continue
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Join Bet Modal */}
      {showJoinModal && selectedBet && (
        <div className="modal-overlay" onClick={() => setShowJoinModal(false)}>
          <div className="join-bet-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Join Coinflip Bet</h2>
              <button className="close-modal" onClick={() => setShowJoinModal(false)}>×</button>
            </div>
            <div className="modal-body">
              <div className="bet-to-join-card">
                <div className="bet-to-join-title">
                  Joining <strong>{selectedBet.creator?.displayName || selectedBet.creatorUsername}'s</strong> bet
                </div>
                <div className="bet-requirements">
                  <div>Required Side: <strong className="highlight-side">{selectedBet.creatorSide === 'heads' ? 'TAILS' : 'HEADS'}</strong></div>
                  <div>Bet Value: <strong>{(selectedBet.totalValue || 0).toLocaleString()} AMP</strong></div>
                  <div>Accepts: <strong>Any value</strong></div>
                </div>
              </div>

              <div className="join-selected-summary">
                <span>Selected: <strong>{getJoinTotalValue().toLocaleString()} AMP</strong></span>
                <span className="status-valid">✓ Any value accepted</span>
              </div>

              <div className="inventory-selection">
                <h4>Select Items from Your Inventory:</h4>
                {userInventory.length === 0 ? (
                  <p className="no-items-text">You have no items in your inventory to bet.</p>
                ) : (
                  <div className="inventory-grid">
                    {userInventory.map((item, index) => {
                      const targetId = item.itemId || item.id;
                      const isSelected = joinSelectedItems.some(i => (i.itemId || i.id) === targetId);

                      return (
                        <div 
                          key={`${targetId}-${index}`} 
                          className={`inventory-item-selectable ${isSelected ? 'selected' : ''}`}
                          onClick={() => toggleJoinItemSelection(item)}
                        >
                          <img
                            src={item.details?.imageUrl || item.image || item.imageUrl || '/default-item.png'}
                            alt={item.details?.name || item.name}
                            className="inventory-item-image"
                            onError={(e) => { e.target.src = '/default-item.png'; }}
                          />
                          <div className="inventory-item-info">
                            <div className="item-name">{item.details?.name || item.name}</div>
                            <div className="item-value">{(item.value || item.details?.value || 0)?.toLocaleString()} AMP</div>
                            <span className={`badge badge-${item.details?.rarity || item.rarity || 'common'}`}>
                              {item.details?.rarity || item.rarity || 'common'}
                            </span>
                          </div>
                          <button 
                            type="button"
                            className={`btn ${isSelected ? 'btn-danger' : 'btn-primary'} btn-sm select-toggle-btn`}
                          >
                            {isSelected ? 'Deselect' : 'Select'}
                          </button>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>

            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={() => setShowJoinModal(false)}>
                Cancel
              </button>
              <button 
                className="btn btn-primary"
                disabled={joining || joinSelectedItems.length === 0}
                onClick={handleConfirmJoinBet}
              >
                {joining ? 'Joining & Flipping...' : `Confirm Bet (${getJoinTotalValue().toLocaleString()} AMP)`}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Create Coinflip Modal */}
      {showCreateModal && (
        <CreateCoinflipModal 
          onClose={() => setShowCreateModal(false)} 
          onCreated={handleBetCreated}
          userId={user?.id}
          socket={socket}
          setBalance={setBalance}
          userInventory={userInventory}
        />
      )}

      {/* Leaderboard Modal */}
      {showLeaderboard && (
        <LeaderboardModal 
          isOpen={showLeaderboard} 
          onClose={() => setShowLeaderboard(false)} 
        />
      )}

      {/* History Modal */}
      {showHistory && (
        <div className="modal-overlay" onClick={() => setShowHistory(false)}>
          <div className="history-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2>Coinflip Bet History</h2>
              <button className="close-modal" onClick={() => setShowHistory(false)}>×</button>
            </div>
            <div className="modal-body">
              {coinflips.filter(cf => cf.isCompleted || cf.status === 'completed').length === 0 ? (
                <div className="no-history-placeholder">
                  <p>No bet history available</p>
                  <p>Place or join a bet to start tracking your history</p>
                </div>
              ) : (
                <div className="history-list">
                  {coinflips.filter(cf => cf.isCompleted || cf.status === 'completed').map((bet, index) => {
                    const isWinner = bet.winnerId === user?.id;
                    return (
                      <div key={index} className="history-item">
                        <div className="history-bet-info">
                          <span className={`bet-result ${isWinner ? 'won' : 'lost'}`}>
                            {isWinner ? 'WON' : 'LOST'}
                          </span>
                          <span className="bet-amount">{(bet.totalValue || 0).toLocaleString()} AMP</span>
                          <span className="bet-side">Result: {bet.result ? bet.result.toUpperCase() : 'N/A'}</span>
                          <span className="bet-date">{new Date(bet.completedAt || bet.updatedAt).toLocaleDateString()}</span>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={() => setShowHistory(false)}>
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Custom animated popup */}
      {showPopup && (
        <AnimatedPopup 
          message={popupMessage} 
          type={popupType} 
          onClose={closePopup}
        />
      )}
    </div>
  );
};

export default CoinflipPage;
